function makeTree(depth) {
    if (depth === 0) return { left: null, right: null };
    return { left: makeTree(depth - 1), right: makeTree(depth - 1) };
}

function checkTree(node) {
    if (node.left === null) return 1;
    return 1 + checkTree(node.left) + checkTree(node.right);
}

function main() {
    const n = parseInt(process.argv[2], 10);
    const minDepth = 4;
    const maxDepth = Math.max(minDepth + 2, n);
    const stretchDepth = maxDepth + 1;

    const out = [];

    // stretch tree
    {
        const t = makeTree(stretchDepth);
        const c = checkTree(t);
        out.push(`stretch tree of depth ${stretchDepth}\t check: ${c}`);
    }

    // long-lived tree
    const longLivedTree = makeTree(maxDepth);

    for (let depth = minDepth; depth <= maxDepth; depth += 2) {
        const iterations = 1 << (maxDepth - depth + minDepth);
        let check = 0;
        for (let i = 0; i < iterations; i++) {
            const t = makeTree(depth);
            check += checkTree(t);
        }
        out.push(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
    }

    out.push(`long lived tree of depth ${maxDepth}\t check: ${checkTree(longLivedTree)}`);

    process.stdout.write(out.join("\n") + "\n");
